CREATE TYPE inspection_review_status AS ENUM ('PENDING_REVIEW','RETURNED_FOR_CORRECTION','RESUBMITTED','APPROVED');
CREATE TYPE correction_item_status AS ENUM ('OPEN','CORRECTED');
CREATE TYPE report_status AS ENUM ('DRAFT','OFFICIAL');
CREATE TABLE inspection_review_cycles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL REFERENCES inspections(id) ON DELETE RESTRICT,cycle_number integer NOT NULL,status inspection_review_status NOT NULL DEFAULT 'PENDING_REVIEW',reviewer_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,return_reason text,resubmitted_at timestamptz,resubmitted_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,approved_at timestamptz,approved_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(inspection_id,cycle_number));
CREATE UNIQUE INDEX inspection_review_one_active_idx ON inspection_review_cycles(inspection_id) WHERE status<>'APPROVED';
CREATE TABLE inspection_review_correction_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),review_cycle_id uuid NOT NULL REFERENCES inspection_review_cycles(id) ON DELETE RESTRICT,bpm_item_id uuid NOT NULL REFERENCES bpm_template_items(id) ON DELETE RESTRICT,correction_reason text NOT NULL, status correction_item_status NOT NULL DEFAULT 'OPEN',marked_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,corrected_at timestamptz,corrected_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,UNIQUE(review_cycle_id,bpm_item_id),CHECK(btrim(correction_reason)<>''));
CREATE TABLE inspection_review_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL REFERENCES inspections(id) ON DELETE RESTRICT,review_cycle_id uuid NOT NULL REFERENCES inspection_review_cycles(id) ON DELETE RESTRICT,event_type varchar(40) NOT NULL,actor_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,reason text,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(event_type=upper(btrim(event_type))));
CREATE TABLE inspection_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL REFERENCES inspections(id) ON DELETE RESTRICT,calculation_id uuid NOT NULL REFERENCES inspection_calculations(id) ON DELETE RESTRICT,status report_status NOT NULL DEFAULT 'DRAFT',storage_path text NOT NULL,file_name varchar(300) NOT NULL,mime_type varchar(100) NOT NULL DEFAULT 'application/pdf',size_bytes bigint NOT NULL,content_sha256 char(64) NOT NULL,generated_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,generated_at timestamptz NOT NULL DEFAULT clock_timestamp(),official_at timestamptz,official_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,CHECK(btrim(storage_path)<>'' AND storage_path !~* '^[a-z][a-z0-9+.-]*:'),CHECK(mime_type='application/pdf' AND size_bytes>0),CHECK(content_sha256=lower(content_sha256) AND content_sha256~'^[0-9a-f]{64}$'),CHECK((status='DRAFT' AND official_at IS NULL AND official_by_user_id IS NULL) OR (status='OFFICIAL' AND official_at IS NOT NULL AND official_by_user_id IS NOT NULL)));
CREATE UNIQUE INDEX inspection_reports_one_official_idx ON inspection_reports(inspection_id) WHERE status='OFFICIAL';
CREATE TABLE inspection_closures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL UNIQUE REFERENCES inspections(id) ON DELETE RESTRICT,case_id uuid NOT NULL REFERENCES cases(id) ON DELETE RESTRICT,official_report_id uuid NOT NULL REFERENCES inspection_reports(id) ON DELETE RESTRICT,closed_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,closed_at timestamptz NOT NULL DEFAULT clock_timestamp(),closure_reason text);
CREATE OR REPLACE FUNCTION review_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN IF NOT EXISTS(SELECT 1 FROM inspections WHERE id=NEW.inspection_id AND status='SUBMITTED') THEN RAISE EXCEPTION 'review requires submitted inspection'; END IF; RETURN NEW; END IF; IF OLD.status='APPROVED' OR NOT ((OLD.status='PENDING_REVIEW' AND NEW.status IN('RETURNED_FOR_CORRECTION','APPROVED')) OR (OLD.status='RETURNED_FOR_CORRECTION' AND NEW.status='RESUBMITTED') OR (OLD.status='RESUBMITTED' AND NEW.status IN('RETURNED_FOR_CORRECTION','APPROVED'))) THEN RAISE EXCEPTION 'invalid review transition'; END IF; IF NEW.status='RETURNED_FOR_CORRECTION' AND NOT EXISTS(SELECT 1 FROM inspection_review_correction_items WHERE review_cycle_id=NEW.id) THEN RAISE EXCEPTION 'return requires correction items'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION correction_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM inspection_review_cycles c JOIN inspections i ON i.id=c.inspection_id JOIN bpm_template_items b ON b.id=NEW.bpm_item_id WHERE c.id=NEW.review_cycle_id AND c.status IN('PENDING_REVIEW','RESUBMITTED') AND b.template_version_id=i.bpm_template_version_id AND b.item_kind='CRITERION' AND b.is_evaluable) THEN RAISE EXCEPTION 'invalid correction item'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION report_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.status='OFFICIAL' THEN RAISE EXCEPTION 'official report immutable'; END IF; IF TG_OP='UPDATE' AND NEW.status='OFFICIAL' AND NOT EXISTS(SELECT 1 FROM inspection_calculations c WHERE c.id=NEW.calculation_id AND c.inspection_id=NEW.inspection_id AND c.is_current) THEN RAISE EXCEPTION 'official report requires current calculation'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE OR REPLACE FUNCTION close_inspection(p_inspection uuid,p_report uuid,p_actor uuid,p_reason text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE c uuid; x uuid; BEGIN SELECT case_id INTO c FROM inspections WHERE id=p_inspection FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM inspection_review_cycles WHERE inspection_id=p_inspection AND status='APPROVED') OR NOT EXISTS(SELECT 1 FROM inspection_reports WHERE id=p_report AND inspection_id=p_inspection AND status='OFFICIAL') THEN RAISE EXCEPTION 'closure requires approved review and official report'; END IF; UPDATE cases SET status='CLOSED',closed_at=clock_timestamp(),closed_reason=coalesce(p_reason,'Inspection closed') WHERE id=c AND status='ASSIGNED'; IF NOT FOUND THEN RAISE EXCEPTION 'case cannot close'; END IF; INSERT INTO inspection_closures(inspection_id,case_id,official_report_id,closed_by_user_id,closure_reason) VALUES(p_inspection,c,p_report,p_actor,p_reason) RETURNING id INTO x; RETURN x; END $$;
CREATE TRIGGER reviews_guard BEFORE INSERT OR UPDATE ON inspection_review_cycles FOR EACH ROW EXECUTE FUNCTION review_guard(); CREATE TRIGGER correction_guard BEFORE INSERT OR UPDATE ON inspection_review_correction_items FOR EACH ROW EXECUTE FUNCTION correction_guard(); CREATE TRIGGER reports_guard BEFORE INSERT OR UPDATE OR DELETE ON inspection_reports FOR EACH ROW EXECUTE FUNCTION report_guard();
